import json
import sys
from pathlib import Path

USAGE = "Usage: python3 todo.py {add <text>|list|done <id>}"
TODO_FILE = "todo.json"


def load_items():
    path = Path(TODO_FILE)
    if not path.exists():
        return []
    with path.open() as f:
        return json.load(f)


def save_items(items):
    with open(TODO_FILE, "w") as f:
        json.dump(items, f, indent=2)


def cmd_add(args):
    text = " ".join(args)
    if len(text) == 0:
        print("Error: add requires <text>", file=sys.stderr)
        print("Usage: python3 todo.py add <text>", file=sys.stderr)
        return 1
    items = load_items()
    new_id = (max((i["id"] for i in items), default=0)) + 1
    items.append({"id": new_id, "text": text, "done": False})
    save_items(items)
    print(f"Added todo {new_id}: {text}")
    return 0


def cmd_list(args):
    if len(args) != 0:
        print("Error: list takes no arguments", file=sys.stderr)
        print("Usage: python3 todo.py list", file=sys.stderr)
        return 1
    items = load_items()
    if not items:
        print("No todos.")
        return 0
    for item in items:
        mark = "x" if item["done"] else " "
        print(f"[{mark}] {item['id']}: {item['text']}")
    return 0


def cmd_done(args):
    if len(args) == 0:
        print("Error: done requires <id>", file=sys.stderr)
        print("Usage: python3 todo.py done <id>", file=sys.stderr)
        return 1
    if len(args) > 1:
        print("Error: done takes exactly one argument", file=sys.stderr)
        print("Usage: python3 todo.py done <id>", file=sys.stderr)
        return 1
    try:
        todo_id = int(args[0])
    except ValueError:
        print(f"Error: invalid id: {args[0]}", file=sys.stderr)
        return 1
    items = load_items()
    for item in items:
        if item["id"] == todo_id:
            item["done"] = True
            save_items(items)
            print(f"Marked todo {todo_id} as done.")
            return 0
    print(f"Error: no todo with id {todo_id}", file=sys.stderr)
    return 2


def main():
    if len(sys.argv) < 2:
        print("Error: missing command", file=sys.stderr)
        print(USAGE, file=sys.stderr)
        return 1

    command = sys.argv[1]
    args = sys.argv[2:]

    if command == "add":
        return cmd_add(args)
    elif command == "list":
        return cmd_list(args)
    elif command == "done":
        return cmd_done(args)
    else:
        print(f"Error: unknown command: {command}", file=sys.stderr)
        print(USAGE, file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

